# I need to get all playlists (both public and private). Let me fetch them with pagination.
spotify_token = spotify_login['access_token']

all_playlists = []
for is_public in [True, False]:
    page_index = 0
    while True:
        result = apis.spotify.show_playlist_library(access_token=spotify_token, is_public=is_public, page_index=page_index, page_limit=20)
        if not result:
            break
        all_playlists.extend(result)
        if len(result) < 20:
            break
        page_index += 1

print(f"Total playlists: {len(all_playlists)}")
for p in all_playlists:
    print(f"ID: {p['playlist_id']}, Title: {p['title']}, Public: {p['is_public']}, Songs: {len(p.get('song_ids', []))}")

